// burst_ctl.sv: the burst sequencer of the shell window (course task): runs `TOTAL` clocks after GO; `en` is MASK[cnt] for the first 32 of them; `idx` counts the enables so far.
module burst_ctl #(
    parameter int TOTAL = 64
) (
    input  logic        clk,
    input  logic        rst,
    input  logic        go,
    input  logic [31:0] mask,
    output logic        active,
    output logic [6:0]  cnt,
    output logic        en,
    output logic [5:0]  idx,
    output logic        done
);
    assign en = active && (cnt < 7'd32) && mask[cnt[4:0]];
    always_ff @(posedge clk) begin
        if (rst) begin
            active <= 1'b0; cnt <= '0; idx <= '0; done <= 1'b0;
        end else if (go) begin
            active <= 1'b1; cnt <= '0; idx <= '0; done <= 1'b0;
        end else if (active) begin
            cnt <= cnt + 1'b1;
            if (en) idx <= idx + 1'b1;
            if (cnt == TOTAL - 1) begin active <= 1'b0; done <= 1'b1; end
        end
    end
endmodule

// c9_median3x3_regs.sv: the shell window of course task c9_median3x3 (burst of windows, medians, a valid record).
module c9_median3x3_regs (
    input  logic        clk,
    input  logic        rst,
    output logic [15:0] led,
    input  logic [6:0]  win_addr,
    input  logic        win_wr,
    input  logic        win_rd,
    input  logic [31:0] win_wdata,
    output logic [31:0] win_rdata
);
    localparam int LAT = 1;
    logic [31:0] mask_r, vmask;
    logic [23:0] wd [24];
    logic [7:0]  outq [8];
    logic [5:0]  nout;
    logic        go, active, en, done, ov;
    logic [6:0]  cnt;
    logic [5:0]  idx;
    logic [7:0]  med;
    wire  [4:0]  base = 5'({2'b00, idx[2:0]} * 3);
    wire  [71:0] cur = {wd[base + 5'd2], wd[base + 5'd1], wd[base]};

    assign led = 16'd0;

    burst_ctl u_burst (.clk(clk), .rst(rst), .go(go), .mask(mask_r), .active(active), .cnt(cnt), .en(en), .idx(idx), .done(done));
    median3x3 u_core (.clk(clk), .rst_n(!rst), .in_valid(en), .win(cur), .out_valid(ov), .med(med));

    always_ff @(posedge clk) begin
        go <= 1'b0;
        if (go) begin nout <= '0; vmask <= '0; end
        else if (active && ov) begin
            if (nout < 6'd8) outq[nout[2:0]] <= med;
            nout <= nout + 1'b1;
            if (cnt >= LAT && cnt - LAT < 7'd32) vmask[cnt - LAT] <= 1'b1;
        end
        if (win_wr) begin
            if (win_addr == 7'h00) mask_r <= win_wdata;
            if (win_addr == 7'h01) go <= 1'b1;
            if (win_addr >= 7'h10 && win_addr < 7'h28) wd[win_addr - 7'h10] <= win_wdata[23:0];
        end
        win_rdata <= 32'd0;
        if (win_rd) begin
            if (win_addr == 7'h00) win_rdata <= mask_r;
            if (win_addr == 7'h02) win_rdata <= {31'd0, done};
            if (win_addr == 7'h03) win_rdata <= {26'd0, nout};
            if (win_addr == 7'h04) win_rdata <= vmask;
            if (win_addr >= 7'h10 && win_addr < 7'h28) win_rdata <= {8'd0, wd[win_addr - 7'h10]};
            if (win_addr >= 7'h30 && win_addr < 7'h38) win_rdata <= (6'(win_addr[2:0]) < nout) ? {24'd0, outq[win_addr[2:0]]} : 32'd0;
        end
        if (rst) begin
            mask_r <= '0; vmask <= '0; nout <= '0; go <= 1'b0; win_rdata <= 32'd0;
            for (int i = 0; i < 24; i++) wd[i] <= '0;
            for (int i = 0; i < 8; i++) outq[i] <= '0;
        end
    end
endmodule

// c9_median3x3_top.sv: board top (Nexys A7-100T, master-XDC port names), test shell DESIGN_ID "MEDN".
// Reference design for course task c9_median3x3; the shell window is wired to c9_median3x3_regs.
module c9_median3x3_top #(
    parameter int          CLKS_PER_BIT   = 868,
    parameter int          TIMEOUT_CYCLES = 100_000,
    parameter logic [31:0] BUILD_STAMP    = 32'h0
) (
    input  logic        CLK100MHZ,
    input  logic        CPU_RESETN,
    output logic [15:0] LED,
    input  logic        UART_TXD_IN,
    output logic        UART_RXD_OUT
);
    logic        clk, rst, win_wr, win_rd;
    logic [6:0]  win_addr;
    logic [31:0] win_wdata, win_rdata;

    assign clk = CLK100MHZ;
    reset_sync u_rst (.clk(clk), .rst_n_async(CPU_RESETN), .rst(rst));

    fpga_shell #(.CLKS_PER_BIT(CLKS_PER_BIT), .TIMEOUT_CYCLES(TIMEOUT_CYCLES),
                 .DESIGN_ID(32'h4d45444e), .BUILD_STAMP(BUILD_STAMP)) u_shell (
        .clk(clk), .rst(rst), .uart_rx(UART_TXD_IN), .uart_tx(UART_RXD_OUT),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));

    c9_median3x3_regs u_regs (
        .clk(clk), .rst(rst), .led(LED),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));
endmodule

// Part 9 lesson 6 reference solution: the 19-compare-exchange median-of-nine network.
module median3x3 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        in_valid,
    input  logic [71:0] win,
    output logic        out_valid,
    output logic [7:0]  med
);
    logic [7:0] v [0:8];
    function automatic logic [15:0] ce(input logic [7:0] a, input logic [7:0] b);      // {smaller, larger}
        ce = (a < b) ? {a, b} : {b, a};
    endfunction
    always_comb begin
        for (int k = 0; k < 9; k++) v[k] = win[k*8 +: 8];
        {v[1], v[2]} = ce(v[1], v[2]); {v[4], v[5]} = ce(v[4], v[5]); {v[7], v[8]} = ce(v[7], v[8]);
        {v[0], v[1]} = ce(v[0], v[1]); {v[3], v[4]} = ce(v[3], v[4]); {v[6], v[7]} = ce(v[6], v[7]);
        {v[1], v[2]} = ce(v[1], v[2]); {v[4], v[5]} = ce(v[4], v[5]); {v[7], v[8]} = ce(v[7], v[8]);
        {v[0], v[3]} = ce(v[0], v[3]); {v[5], v[8]} = ce(v[5], v[8]); {v[4], v[7]} = ce(v[4], v[7]);
        {v[3], v[6]} = ce(v[3], v[6]); {v[1], v[4]} = ce(v[1], v[4]); {v[2], v[5]} = ce(v[2], v[5]);
        {v[4], v[7]} = ce(v[4], v[7]); {v[4], v[2]} = ce(v[4], v[2]); {v[6], v[4]} = ce(v[6], v[4]);
        {v[4], v[2]} = ce(v[4], v[2]);
    end
    always_ff @(posedge clk) begin
        med <= v[4];
        if (!rst_n) out_valid <= 1'b0;
        else        out_valid <= in_valid;
    end
endmodule
